{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Accessible field label shown outside the popover unless isLabelHidden is true.",
      "required": true
    },
    {
      "name": "options",
      "type": "readonly TransferListOption<T>[]",
      "description": "Complete option pool. Each option has value and label, with optional searchable description metadata, group, an isTransferDisabled constraint, and disabledMessage. Which options keep their place is the reorderable object's isReorderable.",
      "required": true
    },
    {
      "name": "value",
      "type": "readonly T[]",
      "description": "Committed selected values in display order. In staged behavior this is the applied value copied into a local draft when the selector opens.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(nextValue: readonly T[]) => void",
      "description": "Called after every permitted list edit in immediate behavior, or once when Apply commits a changed draft in staged behavior.",
      "required": true
    },
    {
      "name": "commitBehavior",
      "type": "TransferListSelectorCommitBehavior",
      "description": "Controls when changes commit. Immediate updates on each list edit without a footer; staged waits for Apply and supports Cancel or dismiss.",
      "default": "'immediate'"
    },
    {
      "name": "triggerLabel",
      "type": "ReactNode",
      "description": "Content shown in the closed selector trigger.",
      "default": "`${value.length} selected`"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Supporting field guidance shown with the external label."
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hides the field label while preserving its accessible name.",
      "default": "false"
    },
    {
      "name": "selectedLabel",
      "type": "string",
      "description": "Heading and accessible name for the selected list.",
      "default": "'Selected'"
    },
    {
      "name": "availableLabel",
      "type": "string",
      "description": "Heading and accessible name for the available list.",
      "default": "'Available'"
    },
    {
      "name": "hasSearch",
      "type": "boolean",
      "description": "Shows a shared search field that filters both lists by label and description.",
      "default": "false"
    },
    {
      "name": "searchLabel",
      "type": "string",
      "description": "Accessible label for the shared search field.",
      "default": "'Search ' followed by label"
    },
    {
      "name": "searchPlaceholder",
      "type": "string",
      "description": "Placeholder shown in the shared search field.",
      "default": "'Search...'"
    },
    {
      "name": "reorderable",
      "type": "Reorderable<T>",
      "description": "Makes the selected options reorderable: pass the object createReorderable makes. Each selected row ends with a reorder handle: on a touch screen hold the handle for a moment, then drag; a mouse drags at once; a tap, a click, Space or Enter on a handle turns on reorder mode for its row, in which each arrow key (or each move in the hint below the handle) moves it a place, and Escape, Done or another activation ends the mode, keeping the moves. The object's isReorderable(value) says which values move: one it rejects has no handle, and at either end of the selected list it also keeps the others from moving past it. In immediate behavior each move goes to the object's onReorder({key, to}); in staged behavior the selector moves its draft instead, so Cancel drops the move with the draft and Apply commits it through onChange. Reordering pauses while a search filters the panel. Without it, the selected options keep their order."
    },
    {
      "name": "hasSelectAll",
      "type": "boolean",
      "description": "Shows Add all and adds every transfer-enabled available option to the current selection.",
      "default": "false"
    },
    {
      "name": "hasClear",
      "type": "boolean",
      "description": "Shows Clear and removes every transfer-enabled selected option from the current selection.",
      "default": "false"
    },
    {
      "name": "renderOption",
      "type": "(option: TransferListOption<T>) => ReactNode",
      "description": "Customizes row content while retaining built-in labels, actions, constraints, and reorder interaction."
    },
    {
      "name": "selectedEmptyText",
      "type": "string",
      "description": "Message shown when the selected list is empty.",
      "default": "'No selected options'"
    },
    {
      "name": "availableEmptyText",
      "type": "string",
      "description": "Message shown when every option has been selected.",
      "default": "'No available options'"
    },
    {
      "name": "noResultsText",
      "type": "string",
      "description": "Message shown when search has no matches in a list.",
      "default": "'No results'"
    },
    {
      "name": "applyLabel",
      "type": "string",
      "description": "Label for the staged Apply action. Only valid with commitBehavior=\"staged\".",
      "default": "'Apply'"
    },
    {
      "name": "cancelLabel",
      "type": "string",
      "description": "Label for the staged Cancel action. Only valid with commitBehavior=\"staged\".",
      "default": "'Cancel'"
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Trigger and field size.",
      "default": "'md'"
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field and its popup; both track this one value.",
      "default": "'min(41rem, calc(100vw - 32px))'"
    },
    {
      "name": "placement",
      "type": "'above' | 'below' | 'start' | 'end'",
      "description": "Popover placement relative to the trigger.",
      "default": "'below'"
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Marks the field optional."
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Marks the field required."
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the selector trigger and transfer interaction."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Shows loading state on the trigger and disables transfer interaction while busy."
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Validation status for the field."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "Placement treatment for the status message."
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text displayed next to the field label."
    },
    {
      "name": "changeAction",
      "type": "(value: readonly T[]) => void | Promise<void>",
      "description": "Optional async action run after each immediate commit or a changed staged Apply; drives optimistic and busy state."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the external selector's bordered control box."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name applied to the external selector's control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles applied to the external selector's control box."
    },
    {
      "name": "data-testid",
      "type": "string",
      "description": "Test ID for the selector trigger button."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
